/* Strata theme: Strata — generated by @strata/theme-engine 0.1.0. Do not edit by hand. */

:root, [data-strata-theme="house"], [data-strata-scheme]:not([data-strata-theme]) {
  color-scheme: light;

  /* Space */
  --strata-space-0: 0px;
  --strata-space-1: 4px;
  --strata-space-2: 8px;
  --strata-space-3: 12px;
  --strata-space-4: 16px;
  --strata-space-5: 20px;
  --strata-space-6: 24px;
  --strata-space-8: 32px;
  --strata-space-10: 40px;
  --strata-space-12: 48px;
  --strata-space-16: 64px;

  /* Radius */
  --strata-radius-button: 8px;
  --strata-radius-field: 8px;
  --strata-radius-container: 12px;
  --strata-radius-badge: 6px;
  --strata-radius-pill: 9999px;

  /* Typography */
  --strata-font-heading: "Inter Tight", "Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --strata-font-body: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --strata-font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --strata-font-heading-tracking: -0.01em;
  --strata-font-size-xs: 12px;
  --strata-font-size-sm: 13px;
  --strata-font-size-md: 14px;
  --strata-font-size-lg: 16px;
  --strata-font-size-xl: 20px;
  --strata-font-size-2xl: 24px;
  --strata-font-size-3xl: 32px;
  --strata-line-height-tight: 1.2;
  --strata-line-height-snug: 1.35;
  --strata-line-height-normal: 1.5;
  --strata-font-weight-regular: 400;
  --strata-font-weight-medium: 500;
  --strata-font-weight-semibold: 600;
  --strata-font-weight-bold: 700;

  /* Motion */
  --strata-motion-duration-fast: 120ms;
  --strata-motion-duration-normal: 200ms;
  --strata-motion-easing: cubic-bezier(0.2, 0, 0, 1);

  /* Colour — light */
  --strata-color-surface-canvas: #f7f7f9;
  --strata-color-surface-default: #fdfdff;
  --strata-color-surface-raised: #fdfdff;
  --strata-color-surface-sunken: #f0f0f2;
  --strata-color-surface-selected: #eeeeef;
  --strata-color-surface-inverse: #1f1f21;
  --strata-color-text-default: #1f1f21;
  --strata-color-text-subtle: #5a5a5d;
  --strata-color-text-disabled: #b1b1b3;
  --strata-color-text-inverse: #fdfdff;
  --strata-color-text-brand: #18181b;
  --strata-color-border-subtle: #dfdfe2;
  --strata-color-border-default: #c8c8cb;
  --strata-color-border-strong: #868688;
  --strata-color-action-primary-bg: #18181b;
  --strata-color-action-primary-fg: #ffffff;
  --strata-color-action-primary-hover: #0f0f12;
  --strata-color-action-primary-pressed: #070709;
  --strata-color-action-primary-border: #18181b;
  --strata-color-action-secondary-bg: #eeeeef;
  --strata-color-action-secondary-fg: #0b0b0d;
  --strata-color-action-secondary-hover: #e4e4e6;
  --strata-color-action-secondary-pressed: #d9d9db;
  --strata-color-accent-bg: #18181b;
  --strata-color-accent-fg: #ffffff;
  --strata-color-accent-subtle: #eeeeef;
  --strata-color-accent-text: #18181b;
  --strata-color-focus-ring: #18181b;
  --strata-color-feedback-success-bg: #dcf7e0;
  --strata-color-feedback-success-fg: #227c3f;
  --strata-color-feedback-success-border: #8bcd98;
  --strata-color-feedback-success-solid: #11813c;
  --strata-color-feedback-success-on-solid: #ffffff;
  --strata-color-feedback-warning-bg: #ffebd1;
  --strata-color-feedback-warning-fg: #8d5e00;
  --strata-color-feedback-warning-border: #e6b061;
  --strata-color-feedback-warning-solid: #efa30f;
  --strata-color-feedback-warning-on-solid: #1f1f21;
  --strata-color-feedback-danger-bg: #ffe9e6;
  --strata-color-feedback-danger-fg: #ba2b29;
  --strata-color-feedback-danger-border: #ff9b90;
  --strata-color-feedback-danger-solid: #d73431;
  --strata-color-feedback-danger-on-solid: #ffffff;
  --strata-color-feedback-info-bg: #e3f0ff;
  --strata-color-feedback-info-fg: #186bb3;
  --strata-color-feedback-info-border: #84c0fe;
  --strata-color-feedback-info-solid: #0f74c5;
  --strata-color-feedback-info-on-solid: #ffffff;

  /* Elevation — light */
  --strata-shadow-raised: 0 1px 2px rgb(16 24 40 / 0.06), 0 1px 3px rgb(16 24 40 / 0.10);
  --strata-shadow-overlay: 0 12px 32px -8px rgb(16 24 40 / 0.18), 0 4px 8px -4px rgb(16 24 40 / 0.08);

  /* Density — comfortable (default) */
  --strata-control-height: 40px;
  --strata-control-padding-inline: 16px;
  --strata-table-row-height: 48px;
  --strata-card-inset: 24px;
  --strata-section-gap: 24px;
  --strata-field-gap: 16px;
}

